	/*
     * @param	event CreateRefundEvent
     */
    @EventHandler( payloadType=CreateRefundEvent.class )
    public void handle( CreateRefundEvent event) {
	    LOGGER.info("handling CreateRefundEvent - " + event );
	    Refund entity = new Refund();
            entity.setRefundId( event.getRefundId() );
            entity.setRefundNumber( event.getRefundNumber() );
            entity.setAmount( event.getAmount() );
            entity.setReason( event.getReason() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRefund( entity );
    }

    /*
     * @param	event UpdateRefundEvent
     */
    @EventHandler( payloadType=UpdateRefundEvent.class )
    public void handle( UpdateRefundEvent event) {
    	LOGGER.info("handling UpdateRefundEvent - " + event );
    	
	    Refund entity = new Refund();
            entity.setRefundId( event.getRefundId() );
            entity.setRefundNumber( event.getRefundNumber() );
            entity.setAmount( event.getAmount() );
            entity.setReason( event.getReason() );
            entity.setCreatedAt( event.getCreatedAt() );
            entity.setPayment( event.getPayment() );
            entity.setOrder( event.getOrder() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindRefund( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRefund( entity );        
    }
    
