    /**
     * Method to retrieve the Refund via an RefundPrimaryKey.
     * @param 	id Long
     * @return 	Refund
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Refund handle( FindRefundQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getRefundId() );
    }
    
    /**
     * Method to retrieve a collection of all Refunds
     *
     * @param	query	FindAllRefundQuery 
     * @return 	List<Refund> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Refund> handle( FindAllRefundQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindRefund,
 * but only if the id matches
 *
 * @param		entity	Refund
 */
	protected void emitFindRefund( Refund entity ) {
		LOGGER.info("handling emitFindRefund" );
		
	    queryUpdateEmitter.emit(FindRefundQuery.class,
	                            query -> query.getFilter().getRefundId().equals(entity.getRefundId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRefund
	 * 
	 * @param		entity	Refund
	 */
	protected void emitFindAllRefund( Refund entity ) {
		LOGGER.info("handling emitFindAllRefund" );
		
	    queryUpdateEmitter.emit(FindAllRefundQuery.class,
	                            query -> true,
	                            entity);
	}

